        urduTranslation: "حضرت عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: 'اسلام کی بنیاد پانچ ستونوں پر رکھی گئی ہے: اس بات کی گواہی دینا کہ اللہ کے سوا کوئی سچا معبود نہیں اور محمد صلی اللہ علیہ وسلم اللہ کے رسول ہیں، اور نماز قائم کرنا، اور زکوٰۃ ادا کرنا، اور حج کرنا، اور رمضان کے روزے رکھنا۔'",
