        urduTranslation: "ہم سے عمرو بن خالد نے بیان کیا، انہوں نے کہا ہم سے زہیر نے بیان کیا، انہوں نے کہا ہم سے ابواسحاق نے بیان کیا، ان کو براء بن عازب رضی اللہ عنہ نے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم جب مدینہ تشریف لائے تو پہلے اپنی نانہال میں اترے، جو انصار تھے۔ اور وہاں آپ صلی اللہ علیہ وسلم نے سولہ یا سترہ ماہ بیت المقدس کی طرف منہ کر کے نماز پڑھی اور آپ صلی اللہ علیہ وسلم کی خواہش تھی کہ آپ کا قبلہ بیت اللہ کی طرف ہو ( جب بیت اللہ کی طرف نماز پڑھنے کا حکم ہو گیا ) تو سب سے پہلی نماز جو آپ صلی اللہ علیہ وسلم نے بیت اللہ کی طرف پڑھی عصر کی نماز تھی۔ وہاں آپ صلی اللہ علیہ وسلم کے ساتھ لوگوں نے بھی نماز پڑھی، پھر آپ کے ساتھ نماز پڑھنے والوں میں سے ایک آدمی نکلا اور اس کا مسجد ( بنی حارثہ ) کی طرف گزر ہوا تو وہ لوگ رکوع میں تھے۔ وہ بولا کہ میں اللہ کی گواہی دیتا ہوں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مکہ کی طرف منہ کر کے نماز پڑھی ہے۔ ( یہ سن کر ) وہ لوگ اسی حالت میں بیت اللہ کی طرف گھوم گئے اور جب رسول اللہ صلی اللہ علیہ وسلم بیت المقدس کی طرف منہ کر کے نماز پڑھا کرتے تھے، یہود اور عیسائی خوش ہوتے تھے مگر جب آپ صلی اللہ علیہ وسلم نے بیت اللہ کی طرف منہ پھیر لیا تو انہیں یہ امر ناگوار ہوا۔ زہیر ( ایک راوی ) کہتے ہیں کہ ہم سے ابواسحاق نے براء سے یہ حدیث بھی نقل کی ہے کہ قبلہ کی تبدیلی سے پہلے کچھ مسلمان انتقال کر چکے تھے۔ تو ہمیں یہ معلوم نہ ہو سکا کہ ان کی نمازوں کے بارے میں کیا کہیں۔ تب اللہ نے یہ آیت نازل کی «وما كان الله ليضيع إيمانكم‏» ( البقرہ: 143 ) ۔",
