        urduTranslation: "ہم سے اسماعیل نے بیان کیا، کہا مجھ سے امام مالک رحمہ اللہ نے بیان کیا، انہوں نے اپنے چچا ابوسہیل بن مالک سے، انہوں نے اپنے باپ (مالک بن ابی عامر) سے، انہوں نے طلحہ بن عبیداللہ سے وہ کہتے تھے نجد والوں میں ایک شخص نبی کریم صلی اللہ علیہ وسلم کے پاس آیا، سر پریشان یعنی بال بکھرے ہوئے تھے، ہم اس کی آواز کی بھنبھناہٹ سنتے تھے اور ہم سمجھ نہیں پا رہے تھے کہ وہ کیا کہہ رہا ہے۔ یہاں تک کہ وہ نزدیک آن پہنچا، جب معلوم ہوا کہ وہ اسلام کے بارے میں پوچھ رہا ہے۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ اسلام دن رات میں پانچ نمازیں پڑھنا ہے، اس نے کہا بس اس کے سوا تو اور کوئی نماز مجھ پر نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا نہیں مگر تو نفل پڑھے ( تو اور بات ہے ) نبی کریم صلی اللہ علیہ وسلم نے فرمایا اور رمضان کے روزے رکھنا۔ اس نے کہا اور تو کوئی روزہ مجھ پر نہیں ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا نہیں مگر تو نفل روزے رکھے ( تو اور بات ہے ) طلحہ نے کہا اور نبی کریم صلی اللہ علیہ وسلم نے اس سے زکوٰۃ کا بیان کیا۔ وہ کہنے لگا کہ بس اور کوئی صدقہ مجھ پر نہیں ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا نہیں مگر یہ کہ تو نفل صدقہ دے ( تو اور بات ہے ) راوی نے کہا پھر وہ شخص پیٹھ موڑ کر چلا۔ یوں کہتا جاتا تھا، قسم اللہ کی میں نہ اس سے بڑھاؤں گا نہ گھٹاؤں گا، نبی کریم صلی اللہ علیہ وسلم نے فرمایا اگر یہ سچا ہے تو اپنی مراد کو پہنچ گیا۔",
